	@Test
	void prepaidInspectionCoversTraversalAndDoesNotReviveSpentCredit() throws Exception {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(4096L, 4096L);
		Value literal = VF.createLiteral("small");
		Value later = VF.createIRI("urn:later");
		try (var ledger = manager.openQuery();
				var row = NativeValuePayloads.tryInspectionRow(ledger, 1024L,
						NativeValuePayloads.inspectionScratchBytes(2));
				var active = row.activate()) {
			long prepaid = manager.usedBytes();
			assertThat(NativeValuePayloads.beforeInspection(literal, null)).isSameAs(literal);
			assertThat(manager.usedBytes()).as("the admitted fixed traversal is consumed without another reservation")
					.isEqualTo(prepaid);
			row.finishDecoded(new NativeResultRow(new String[] { "value" },
					new NativeResultCell[] { NativeResultCell.term(literal) }));
			try (var remaining = ledger.reserve(ledger.maxBytes() - ledger.usedBytes(), null)) {
				assertThat(remaining).isNotNull();
				assertThatThrownBy(() -> NativeValuePayloads.beforeInspection(later, null))
						.isInstanceOf(NativeValuePayloads.AdmissionRefused.class);
			}
		}
		assertThat(manager.usedBytes()).isZero();
	}

