	@Test
	void compositeParallelReaderAdmitsColdDictionaryValues(@TempDir Path directory) throws Exception {
		LmdbStore store = new LmdbStore(directory.toFile(), new LmdbStoreConfig().setNativeEvaluationEnabled(true));
		SailRepository repository = new SailRepository(store);
		repository.init();
		String label = "composite-parallel-cold-payload".repeat(64);
		Value value = VF.createLiteral(label);
		try {
			try (var connection = repository.getConnection()) {
				connection.add(VF.createIRI("urn:admission:explicit"), VF.createIRI("urn:admission:p"), value);
			}
			try (InferencerConnection connection = (InferencerConnection) store.getConnection()) {
				connection.begin();
				connection.addInferredStatement(VF.createIRI("urn:admission:inferred"), VF.createIRI("urn:admission:p"),
						value);
				connection.commit();
			}
			try (var explicitDataset = NativeQuerySourceAccess.openExplicitDataset(store);
					var inferredDataset = NativeQuerySourceAccess.openInferredDataset(store)) {
				NativeLmdbQuerySource explicit = (NativeLmdbQuerySource) explicitDataset;
				NativeLmdbQuerySource inferred = (NativeLmdbQuerySource) inferredDataset;
				assertThat(explicit.hasStatementsInSource()).isTrue();
				assertThat(inferred.hasStatementsInSource()).isTrue();
				NativeLmdbQuerySource composite = CompositeNativeLmdbQuerySource.combine(List.of(explicit, inferred));
				assertThat(composite).isNotNull();
				long id = composite.idOf(value);
				assertThat(id).isNotEqualTo(NativeLmdbQuerySource.UNKNOWN_ID);
				NativeLmdbQuerySource.ParallelSource[] opened = composite.openParallelSources(1);
				assertThat(opened).hasSize(1);
				try (var parallel = opened[0]) {
					LmdbValue captured = (LmdbValue) parallel.lazyValue(id);
					LmdbLiteral cold = new LmdbLiteral(captured.getValueStoreRevision(), id);
					AtomicLong admitted = new AtomicLong();
					assertThat(parallel.initializeAdmittedValue(cold, admitted::addAndGet))
							.as("a composite worker must delegate admission to its retained dictionary source")
							.isTrue();
					assertThat(admitted.get()).isPositive();
					assertThat(cold.getLabel()).isEqualTo(label);

					LmdbLiteral refused = new LmdbLiteral(captured.getValueStoreRevision(), id);
					assertThatThrownBy(() -> parallel.initializeAdmittedValue(refused, bytes -> {
						throw new IllegalStateException("admission refused");
					})).isInstanceOf(IllegalStateException.class).hasMessage("admission refused");
					assertThat(refused.isInitialized()).isFalse();

					LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(1L << 20, 1L << 20);
					LmdbLiteral inspected = new LmdbLiteral(captured.getValueStoreRevision(), id);
					try (var ledger = manager.openQuery();
							var row = NativeValuePayloads.row(ledger, 1024L, 1024L);
							var scope = row.activate()) {
						assertThat(NativeValuePayloads.beforeInspection(inspected, parallel).stringValue())
								.isEqualTo(label);
						assertThat(inspected.isInitialized()).isFalse();
					}
					assertThat(manager.usedBytes()).isZero();
				}
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void detachedNativePayloadTransfersToRuntimeOwnership() throws Exception {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(2L << 20, 2L << 20);
		LmdbLiteral original = new LmdbLiteral(new ValueStoreRevision.Default(null), 1L);
		String label = "retained".repeat(8192);
		Value prepared;
		try (var ledger = manager.openQuery();
				var table = new NativeRuntimeValueTable(new AtomicLong(RUNTIME_INTERN_BASE),
						new NativeRuntimeValueTable.Budget(1L << 20, ledger))) {
			long id;
			try (var row = NativeValuePayloads.row(ledger, 1024L, 1024L); var scope = row.activate()) {
				prepared = NativeValuePayloads.beforeInspection(original, sourceFor(label));
				row.finishDecoded(new NativeResultRow(new String[] { "value" },
						new NativeResultCell[] { NativeResultCell.term(prepared) }));
				long before = manager.usedBytes();
				id = table.intern(prepared, false);
				assertThat(manager.usedBytes() - before)
						.isLessThan(NativeRuntimeValueTable.retainedValueBytes(prepared, 0));
			}
			assertThat(original.isInitialized()).isFalse();
			assertThat(table.valueOf(id)).isSameAs(prepared);
			assertThat(manager.usedBytes()).isGreaterThanOrEqualTo(
					NativeRuntimeValueTable.retainedValueBytes(prepared, 0));
		}
		assertThat(manager.usedBytes()).isZero();
	}

