	@Test
	void runtimeAdoptsOnePayloadChargeAndKeepsItAfterReaderClose() throws Exception {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(2L << 20, 2L << 20);
		try (var ledger = manager.openQuery()) {
			Value value = VF.createLiteral("x".repeat(64 * 1024));
			long payload = NativeRuntimeValueTable.retainedValueBytes(value, 0);
			NativeRuntimeValueTable.Budget budget = new NativeRuntimeValueTable.Budget(1L << 20, ledger);
			try (NativeRuntimeValueTable table = new NativeRuntimeValueTable(new AtomicLong(RUNTIME_INTERN_BASE),
					budget)) {
				long id;
				try (NativeValuePayloads.Row row = admitted(ledger, value)) {
					long before = manager.usedBytes();
					try (NativeValuePayloads.Scope ignored = row.activate()) {
						id = table.intern(value, false);
					}
					assertThat(manager.usedBytes() - before)
							.as("adoption adds table metadata, not a second charge for the shared lexical payload")
							.isLessThan(payload);
					assertThat(budget.usedBytes()).as("the local runtime limit still counts adopted payload")
							.isGreaterThanOrEqualTo(payload);
				}
				assertThat(table.valueOf(id)).isSameAs(value);
				assertThat(manager.usedBytes()).as("runtime ownership outlives the originating reader")
						.isGreaterThanOrEqualTo(payload);
			}
			assertThat(manager.usedBytes()).isZero();
		}
	}

