	@Test
	void concurrentActiveScopesKeepPayloadAliveAfterTheReaderOwnerCloses() throws Exception {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(1L << 20, 1L << 20);
		Value value = VF.createLiteral("shared");
		try (var ledger = manager.openQuery();
				NativeValuePayloads.Row row = admitted(ledger, value);
				var workers = Executors.newFixedThreadPool(2)) {
			CountDownLatch ready = new CountDownLatch(2), release = new CountDownLatch(1);
			var first = workers.submit(() -> {
				try (var scope = row.activate(); var claim = NativeValuePayloads.adopt(value)) {
					assertThat(claim).isNotNull();
					ready.countDown();
					assertThat(release.await(10, TimeUnit.SECONDS)).isTrue();
				}
				return null;
			});
			var second = workers.submit(() -> {
				try (var scope = row.activate(); var claim = NativeValuePayloads.adopt(value)) {
					assertThat(claim).isNotNull();
					ready.countDown();
					assertThat(release.await(10, TimeUnit.SECONDS)).isTrue();
				}
				return null;
			});
			try {
				assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
				row.close();
				assertThat(manager.usedBytes()).isPositive();
			} finally {
				release.countDown();
			}
			first.get(10, TimeUnit.SECONDS);
			second.get(10, TimeUnit.SECONDS);
			assertThat(manager.usedBytes()).isZero();
		}
	}

